INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('e0e7419b-dccd-4338-857f-b10c74f68d83', 'ACP-Q-0290', 1, 'published', 'p-mpharm', 'sub-paed-dose', 'hard', 'calculation', 'gp', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('dd07fcaf-7309-4c1c-978d-44dc855d0cbc', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'A hospital patient is prescribed 1 litre of sodium chloride 0.9% containing 40 mmol potassium chloride to be infused over 8 hours. The giving set delivers 20 drops per mL. (Case Ref: CALCULATIONS-0290). Relevant physiological and medication history have been reviewed.', 'What is the required infusion rate in drops per minute (drops/min)? Round to the nearest whole drop.', '42', '1', 'drops/min', NULL, 1, '(1000 * 20) / (8 * 60) = 20000 / 480 = 41.67 drops/min = 42 drops/min.', 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('abd1762e-aa80-4efe-83da-09752b61fab4', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'A', '42 drops/min', 1, 'Correct. Total volume = 1,000 mL. Total time = 8 hours * 60 minutes = 480 minutes. Total drops = 1,000 mL * 20 drops/mL = 20,000 drops. 20,000 / 480 = 41.67 drops/min = 42 drops/min.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('2fd477f0-347d-4338-a7e8-f59e6f1af602', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'B', '21 drops/min (calculated based on 10 drops/mL giving set)', 0, 'Incorrect giving set factor used.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a103f365-a116-49dc-ae26-95c5f80e2cb8', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'C', '83 drops/min (exceeds safe maximum IV potassium infusion rate of 20 mmol/hr)', 0, 'Unsafe infusion rate causing cardiac arrest risk from rapid potassium administration.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('781d1414-d882-419b-9e3e-47436c79f736', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'D', '125 drops/min (infused over 2 hours instead of 8 hours)', 0, 'Dangerous rate violation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('993388de-3fd7-4e86-9421-202ba59bc83b', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'E', '50 drops/min', 0, 'Rounding error resulting in infusion completing ahead of schedule.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('ce40f0b3-ce66-4490-b6b6-2d06e3e9e541', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 'Infusion rate (drops/min) = (Volume in mL * Drop factor) / (Time in hours * 60).', 'Maximum peripheral potassium infusion rate should generally not exceed 10 to 20 mmol/hour. Reference: BNF Chapter 9 / GPhC Paper 1 Standards.', 'BNF Chapter 9 / GPhC Paper 1 Standards', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('df169b91-2c5e-48e6-b816-8ac0123fecac', 'e0e7419b-dccd-4338-857f-b10c74f68d83', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('5a7ae032-33ce-4d72-8db0-1e53615a9474', 'ACP-Q-0291', 1, 'published', 'p-mpharm', 'sub-crcl', 'medium', 'calculation', 'hospital', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('9fbb6044-9283-4639-be6e-c9c6250e0ad1', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'A 74-year-old female patient weighing 58 kg presents with serum creatinine of 115 micromol/L. She is being assessed for apixaban stroke prevention in non-valvular atrial fibrillation. (Case Ref: CALCULATIONS-0291). Relevant physiological and medication history have been reviewed.', 'Calculate the patient’s estimated creatinine clearance (CrCl) in mL/min using the Cockcroft-Gault formula. Give your answer to the nearest whole number.', '37', '1', 'mL/min', NULL, 1, '((140 - 74) * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 mL/min. With 1.04 constant = 37.3 mL/min.', 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e807be82-d34f-422c-ae71-f9cef3402e37', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'A', '37 mL/min', 1, 'Correct. Cockcroft-Gault formula: ((140 - Age) * Weight in kg * 1.04) / Serum Creatinine in micromol/L. ((140 - 74) * 58 * 1.04) / 115 = (66 * 58 * 1.04) / 115 = 3981.12 / 115 = 34.6 -> adjusted for female factor = 37.8 mL/min (approx 35-37 mL/min depending on constant 1.04 vs 0.85).', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('0726fbe7-f408-4d2b-b63a-3d34461b431f', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'B', '44 mL/min (omitted female correction factor of 1.04 vs 1.23 for males)', 0, 'Incorrect. Forgets female adjustment factor (1.04).', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('e1ab2f2c-2fbf-4e1c-904e-9338d16b766d', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'C', '52 mL/min (used MDRD eGFR instead of Cockcroft-Gault CrCl)', 0, 'Clinically unsafe. MHRA specifically warns against using eGFR for drug dosing in older adults or extreme weights.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('5d1d0732-0141-41d2-a875-7dd1501fcb9b', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'D', '25 mL/min (severe underestimation)', 0, 'Calculation error leading to inappropriate drug discontinuation.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('54aeaf3e-7310-4a96-806d-b12647014a68', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'E', '60 mL/min (assumed normal without calculation)', 0, 'Presuming renal clearance based purely on age without calculation is clinically dangerous.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('e98b9fed-e7cc-4b7d-b4f5-ca6fe0ab7c07', '5a7ae032-33ce-4d72-8db0-1e53615a9474', 'Always use the Cockcroft-Gault formula for renal dose adjustments: Male: ((140-age)*wt*1.23)/Cr; Female: ((140-age)*wt*1.04)/Cr.', 'Units: Age (years), Weight (kg), Serum Creatinine (micromol/L). Reference: GPhC Calculations Guidance & BNF Dosing Framework.', 'GPhC Calculations Guidance & BNF Dosing Framework', 1789735204, 1789735204);
