INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('e3dbc913-e9db-4561-92df-b04f59925f95', 'df3aada1-7742-4899-a3d6-1195fa48c689', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('ab48e576-f061-41b3-93e9-579257c0ad40', 'ACP-Q-0374', 1, 'published', 'p-mpharm', 'sub-parkinson', 'hard', 'sba', 'gp', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('fa2fa099-3cfc-46cf-904b-3866e20a0ac3', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'A 52-year-old patient taking Lithium carbonate 800 mg at bedtime presents with severe coarse hand tremor, ataxia, nausea, and persistent muscle weakness. Recent GP notes indicate an NSAID was started for lower back pain 5 days ago. (Case Ref: CNS-0374). Relevant physiological and medication history have been reviewed.', 'What is the immediate clinical interpretation and management step?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('779bc6b8-6d0c-4b1f-9e66-6c7283905099', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'A', 'Suspect lithium toxicity precipitated by NSAID; withhold lithium and arrange immediate emergency department assessment for serum level', 1, 'Correct. NSAIDs decrease renal excretion of lithium leading to dangerous accumulation. Coarse tremor, ataxia, and diarrhoea indicate toxic levels (> 1.5 - 2.0 mmol/L).', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('f0142554-29e4-4610-9237-132e347f215c', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'B', 'Advise patient to halve lithium dose and book routine phlebotomy next week', 0, 'Sub-optimal and dangerous. Lithium toxicity is a medical emergency requiring acute secondary care assessment.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a2cfcef5-9d21-4111-8729-dd3e436ade50', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'C', 'Add Propranolol 40 mg twice daily to treat the tremor', 0, 'Fatal mistake. Masking coarse tremor with a beta-blocker delays diagnosis of worsening neurotoxicity and renal damage.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('3971cf4f-2d8a-4d2e-a694-556e2ad3dfa8', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'D', 'Switch from lithium carbonate to lithium citrate syrup at equivalent dose', 0, 'Irrelevant change that does not address systemic drug toxicity.', 3, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('53ecbf50-e3e7-417d-91df-883ec720474d', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'E', 'Measure 4-hour post-dose serum lithium level', 0, 'Incorrect sampling timing. Serum lithium levels must strictly be sampled 12 hours post-dose.', 4, 1789735204);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('48d03a75-616e-403b-81bb-c08b2a6d10a0', 'ab48e576-f061-41b3-93e9-579257c0ad40', 'NSAIDs, ACE inhibitors, and thiazide diuretics cause lithium retention. 12-hour post-dose level is mandatory.', 'Target serum range is 0.6 - 0.8 mmol/L (0.8 - 1.0 for acute mania). Toxicity features: coarse tremor, ataxia, hyperreflexia, convulsions. Reference: NICE CG185 & BNF Section 4.2.3.', 'NICE CG185 & BNF Section 4.2.3', 1789735204, 1789735204);
INSERT INTO question_governance (id, question_id, clinical_approved_at, educational_approved_at, copy_editor_approved_at, approved_at, conflict_of_interest, created_at, updated_at) VALUES ('85e07bd0-2397-4043-8ee6-c09bc6940249', 'ab48e576-f061-41b3-93e9-579257c0ad40', 1789735204, 1789735204, 1789735204, 1789735204, 0, 1789735204, 1789735204);
INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('04970d16-44f9-4527-94c7-1b5ee3df64b2', 'ACP-Q-0375', 1, 'published', 'p-mpharm', 'sub-substance', 'medium', 'sba', 'hospital', 'human', 1789735204, 1789735204, 1789735204);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('6bc296b1-c307-42eb-8f20-3195559dff2b', '04970d16-44f9-4527-94c7-1b5ee3df64b2', 'A 26-year-old female with generalised epilepsy attends community pharmacy for a repeat prescription of Sodium Valproate 500 mg tablets. She mentions she stopped using contraception two months ago. (Case Ref: CNS-0375). Relevant physiological and medication history have been reviewed.', 'What is the essential action for the pharmacist to take before dispensing this medication?', NULL, NULL, NULL, NULL, 1, NULL, 1789735204, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4de12ef3-9bbd-46f5-aa7d-1873c6dd7e45', '04970d16-44f9-4527-94c7-1b5ee3df64b2', 'A', 'Confirm active enrollment in the Valproate Pregnancy Prevention Programme (prevent) with signed Annual Risk Acknowledgement and immediate referral to prescriber', 1, 'Correct. Valproate is strictly contraindicated in women of childbearing potential unless conditions of the Pregnancy Prevention Programme are met due to 10% teratogenicity and 30-40% neurodevelopmental disorders.', 0, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6d39daa4-2df4-40c6-a876-a6c24271fdf0', '04970d16-44f9-4527-94c7-1b5ee3df64b2', 'B', 'Dispense the full 3-month supply and advise patient to buy over-the-counter pregnancy test', 0, 'Sub-optimal and regulatory failure. Pharmacists must verify Annual Risk Acknowledgement form before dispensing.', 1, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6ede1060-97ce-4326-bf4b-61e291fd642b', '04970d16-44f9-4527-94c7-1b5ee3df64b2', 'C', 'Switch patient immediately to Carbamazepine without specialist neurology consult', 0, 'Unsafe practice. Pharmacists cannot substitute anticonvulsants without specialist prescriber consultation due to status epilepticus risk.', 2, 1789735204);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('970b3304-bc2a-4a31-8dd8-89b4baefc364', '04970d16-44f9-4527-94c7-1b5ee3df64b2', 'D', 'Provide manufacturer patient leaflet only and dispense as routine', 0, 'Deprecated pre-2018 practice. Mandatory legal checks are now in place under MHRA regulations.', 3, 1789735204);
